/* Usability fixes round 2. */
test("reads items from a buyer's message",()=>{const s=parseOrder("Please send 60 dupattas and 12 kurta sets for Pongal stock.");eq(s,{p4:60,p5:12});eq(parseOrder("20 rolls of organic cotton and 10 of linen").p2,20)});
test("make a quote from a message in a B2B chat",()=>{setView("owner");openChat("c10");const c=C("c10"),i=c.msgs.findIndex(m=>/60 dupattas/.test(m.text||""));S.sheet={type:"ckmsg",i};render();ok(document.querySelector('[data-act="ckmkorder"]'));act.ckmkorder();eq(S.sheet.type,"quote");eq(S.sheet.sel.p4,60);S.sheet=null});
test("header actions are labelled",()=>{setView("owner");S.tab="chats";S.stack=[{name:"tab"}];render();ok(/Ask AI/.test(document.querySelector(".lx-top").innerText));ok(document.querySelector(".hdr-pill"))});
test("pending puts overdue first and reminds everyone overdue",()=>{addDoc({id:"INV-T6",kind:"invoice",chat:"c10",items:[{pid:"p4",qty:5,price:1940}],terms:"Net 15",due:"1 Nov",dueTs:Date.now()-9*864e5,status:"unpaid"});setView("owner");S.tab="pending";S.stack=[{name:"tab"}];render();const first=document.querySelector("#app .secttl h3");ok(/overdue/i.test(first.textContent),first.textContent);
  const n=C("c10").msgs.length;act.remindall();ok(C("c10").msgs.length>n);delete S.docs["INV-T6"]});
test("counter bill saves as paid in cash without a phone number",()=>{setView("owner");act.counterbill();S.sheet.custom=[{name:"Blouse piece",qty:1,price:250}];const before=new Set(Object.keys(S.docs));submitSheet();const d=Object.values(S.docs).find(x=>!before.has(x.id)&&x.kind==="invoice");eq(d.status,"paid");eq(d.paidHow,"Cash at counter")});
test("app lock asks for a PIN on money screens",()=>{setView("owner");act.locktoggle();S.tab="biz";S.stack=[{name:"tab"}];render();ok(!S.sheet||S.sheet.type!=="applock","just turned on, still unlocked");
  act.locktoggle();act.locktoggle();});
test("delivery address can be changed",()=>{setView("customer");S.sheet={type:"order",pid:"p4",qty:1,v:"Rose",ship:"std",pay:"cod"};render();act.addrpick({dataset:{i:"1"}});const o=placeOrder("c1",[{pid:"p4",qty:1,price:2400}],"cod",78);ok(/Infopark/.test(o.addr));S.addr=0;S.sheet=null});
test("add product: own category and HSN picked for you",()=>{setView("owner");S.np={name:"Rose face mist",desc:"",cat:"Sarees",price:"450",whole:"",moq:"5",stock:"20",reorder:"5",hsn:"",vars:"",vis:"Everyone",color:"#C06C84",photos:0};S.stack=[{name:"tab"},{name:"addproduct"}];render();
  ok(document.getElementById("app").innerHTML.includes("e.g. 1,200"));act.newcat();document.getElementById("newcat_i").value="Skincare";act.newcatgo();eq(S.np.cat,"Skincare");S.stack=[{name:"tab"}];S.np=null});
